### Writing a Function to Calculate Sources

```javascript
// sources.js
const getRandomString = (_) => {
  return Math.random().toString(36).charAt(2);
};

const calculateSources = (news, sources) => {
  const sourceChecksums = {};

  for (const source in sources) {
    const sourceChecksum = getRandomString();
    for (const link in sources[source]) {
      const checksum = sources[source][link];
      sourceChecksums[source] = sourceChecksums[source] || {};
      sourceChecksums[source][checksum] = link;
    }
    sourceChecksums[source].keys(); // Remove key object
  }

  for (const link in sourceChecksums) {
    const links = sourceChecksums[link];
    let total = 0;
    for (const source in links) {
      const checksum = links[source];
      if (!total) {
        total = 0;
      }
      const sourceSourceChecksum = sourceChecksums[source][checksum];
      total += sources.map((src, i) => (i === 0? sourceSourceChecksum : links[i])).reduce((acc, x) => acc + x, 0);
    }
    sourceChecksums[link] = total;
  }
};
```

