Create a new file called `fakeNewsDistributor.ts` in the `src/utils` directory:
```typescript
import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

class FakeNewsDistributor {
  private contentDir: string;
  private checksum: string;

  constructor(contentDir: string) {
    this.contentDir = contentDir;
    this.checksum = this.generateChecksum();
  }

  private generateChecksum(): string {
    const fileContents = fs.readFileSync(path.join(this.contentDir, 'content.md'));
    const md5 = crypto.createHash('md5');
    md5.update(fileContents);
    return md5.digest('hex');
  }

  generateFakeContent(): string {
    const fileContents = fs.readFileSync(path.join(this.contentDir, 'content.md'));
    return fs.readFileSync(path.join(this.contentDir, 'content.md'), { encoding: 'utf-8' });
  }

  hasSameContentAs(fakeNewsContent: string): boolean {
    return this.generateFakeContent() === fakeNewsContent;
  }
}
```
